  wire \cpu_pwdata[7] ;
  wire [7:0] midbus ;
  ICV_WRAP_X X0 ( .CLK(CLK) , .RST(RST_N) , .A(DIN[0]) , .Y(\cpu_pwdata[7]) , .VDD(VDD) , .VSS(VSS) ) ;
  ICV_WRAP_P X1 ( .A(\cpu_pwdata[7]) , .Y(midbus[0]) , .VDD(VDD) , .VSS(VSS) ) ;
  ICV_WRAP_R X2 ( .A(midbus[0]) , .Y(DOUT[0]) , .VDD(VDD) , .VSS(VSS) ) ;
